import { spawn } from 'child_process';
import * as fs from 'fs/promises';
import * as os from 'os';
import * as path from 'path';
import {
  assertApprovedReviewAgentBinary,
  type ApprovedReviewAgent,
} from '../control-plane/approved-review-agent';

export const CODEX_OAUTH_PINNED_CODEX_PACKAGE = '@openai/codex@0.147.0';

const CODEX_OAUTH_CLI_INSTALL_TIMEOUT_MS = 300_000;

export type PreparedCodexCli = {
  binaryPath: string;
  clear?(): Promise<void>;
};

type CodexCliLogger = {
  info(message: string): void;
  warn(message: string): void;
};

export async function prepareCodexCliBeforeAuthRead(
  input: {
    logger?: CodexCliLogger;
    timeoutMs?: number;
    signal?: AbortSignal;
    approvedAgent?: ApprovedReviewAgent;
  } = {}
): Promise<PreparedCodexCli> {
  input.signal?.throwIfAborted();
  if (input.approvedAgent) {
    const profile = input.approvedAgent;
    if (
      profile.agentKind !== 'codex' ||
      process.platform !== 'linux' ||
      process.arch !== 'x64'
    )
      throw new Error('review_agent_toolchain_unavailable');
    if (
      !/^[0-9]+\.[0-9]+\.[0-9]+(?:-[A-Za-z0-9.-]+)?$/.test(
        profile.packageVersion
      )
    )
      throw new Error('review_agent_package_version_invalid');
    const installRoot = await fs.mkdtemp(
      path.join(os.tmpdir(), 'reviewrouter-approved-agent-')
    );
    try {
      await runNpmInstall({
        installRoot,
        packageVersion: profile.packageVersion,
        timeoutMs: input.timeoutMs ?? CODEX_OAUTH_CLI_INSTALL_TIMEOUT_MS,
        signal: input.signal,
      });
      const triple = 'x86_64-unknown-linux-musl/bin/codex';
      const candidates = [
        path.join(installRoot, 'node_modules/@openai/codex/vendor', triple),
        path.join(
          installRoot,
          'node_modules/@openai/codex-linux-x64/vendor',
          triple
        ),
        path.join(
          installRoot,
          'node_modules/@openai/codex/node_modules/@openai/codex-linux-x64/vendor',
          triple
        ),
      ];
      for (const candidate of candidates) {
        let binaryPath: string;
        try {
          binaryPath = await fs.realpath(candidate);
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue;
          throw error;
        }
        const relative = path.relative(installRoot, binaryPath);
        if (
          relative === '..' ||
          relative.startsWith(`..${path.sep}`) ||
          path.isAbsolute(relative)
        )
          throw new Error('review_agent_binary_path_invalid');
        assertApprovedReviewAgentBinary(profile, await fs.readFile(binaryPath));
        return {
          binaryPath,
          clear: () => fs.rm(installRoot, { recursive: true, force: true }),
        };
      }
      throw new Error('review_agent_binary_missing');
    } catch (error) {
      try {
        await fs.rm(installRoot, { recursive: true, force: true });
      } catch {
        input.logger?.warn(
          'Codex CLI install cleanup failed; removal unconfirmed'
        );
      }
      throw error;
    }
  }
  const explicit = process.env.REVIEWROUTER_CODEX_BINARY?.trim();
  if (explicit) {
    await assertCodexBinaryWorks(
      explicit,
      input.timeoutMs ?? 10_000,
      input.signal
    );
    return { binaryPath: explicit };
  }

  if (
    await canRunCodexBinary('codex', input.timeoutMs ?? 10_000, input.signal)
  ) {
    return { binaryPath: 'codex' };
  }

  input.logger?.info(
    `Codex CLI not found on PATH; installing ${CODEX_OAUTH_PINNED_CODEX_PACKAGE} before auth materialization.`
  );
  const installRoot = await fs.mkdtemp(
    path.join(os.tmpdir(), 'reviewrouter-codex-cli-')
  );
  try {
    await runNpmInstall({
      installRoot,
      timeoutMs: input.timeoutMs ?? CODEX_OAUTH_CLI_INSTALL_TIMEOUT_MS,
      signal: input.signal,
    });
    const binaryPath = path.join(installRoot, 'node_modules', '.bin', 'codex');
    await assertCodexBinaryWorks(
      binaryPath,
      input.timeoutMs ?? 10_000,
      input.signal
    );
    return {
      binaryPath,
      async clear() {
        await fs.rm(installRoot, { recursive: true, force: true });
      },
    };
  } catch (error) {
    try {
      await fs.rm(installRoot, { recursive: true, force: true });
    } catch {
      input.logger?.warn(
        'Codex CLI install cleanup failed; removal unconfirmed'
      );
    }
    throw error;
  }
}

async function assertCodexBinaryWorks(
  binaryPath: string,
  timeoutMs: number,
  signal?: AbortSignal
): Promise<void> {
  if (!(await canRunCodexBinary(binaryPath, timeoutMs, signal))) {
    throw new Error('codex_oauth_codex_cli_unavailable');
  }
}

async function canRunCodexBinary(
  binaryPath: string,
  timeoutMs: number,
  signal?: AbortSignal
): Promise<boolean> {
  try {
    await runCommand(binaryPath, ['--version'], {
      timeoutMs,
      signal,
      cwd: os.tmpdir(),
      env: safePreAuthEnv(),
    });
    return true;
  } catch {
    signal?.throwIfAborted();
    return false;
  }
}

async function runNpmInstall(input: {
  installRoot: string;
  timeoutMs: number;
  signal?: AbortSignal;
  packageVersion?: string;
}): Promise<void> {
  await runCommand(
    'npm',
    [
      'install',
      '--prefix',
      input.installRoot,
      '--omit=dev',
      '--no-audit',
      '--no-fund',
      ...(input.packageVersion ? ['--ignore-scripts'] : []),
      input.packageVersion
        ? `@openai/codex@${input.packageVersion}`
        : CODEX_OAUTH_PINNED_CODEX_PACKAGE,
    ],
    {
      timeoutMs: input.timeoutMs,
      signal: input.signal,
      cwd: input.installRoot,
      env: safePreAuthEnv(),
    }
  );
}

function runCommand(
  command: string,
  args: readonly string[],
  options: {
    timeoutMs: number;
    cwd: string;
    env: NodeJS.ProcessEnv;
    signal?: AbortSignal;
  }
): Promise<void> {
  options.signal?.throwIfAborted();
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: options.cwd,
      detached: options.signal !== undefined && process.platform !== 'win32',
      env: options.env,
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let stderr = '';
    let timedOut = false;
    const stop = () => {
      try {
        if (options.signal && process.platform !== 'win32' && child.pid)
          process.kill(-child.pid, 'SIGKILL');
        else child.kill('SIGKILL');
      } catch {
        child.kill('SIGKILL');
      }
    };
    options.signal?.addEventListener('abort', stop, { once: true });
    if (options.signal?.aborted) stop();
    const timer = setTimeout(() => {
      timedOut = true;
      stop();
    }, options.timeoutMs);
    const finish = () => {
      clearTimeout(timer);
      options.signal?.removeEventListener('abort', stop);
    };
    child.stderr?.on('data', (chunk) => {
      stderr += String(chunk);
    });
    child.on('error', (error) => {
      if (child.pid) return;
      finish();
      reject(
        new Error(
          `codex_oauth_codex_cli_prepare_failed:${safeOutput(String(error))}`
        )
      );
    });
    child.on('close', (code) => {
      finish();
      // Await subprocess close before deleting the install root.
      if (options.signal?.aborted || timedOut) {
        reject(
          options.signal?.aborted
            ? options.signal.reason
            : new Error('codex_oauth_codex_cli_prepare_timeout')
        );
        return;
      }
      if (code === 0) {
        resolve();
        return;
      }
      reject(
        new Error(
          `codex_oauth_codex_cli_prepare_failed:${code ?? 'signal'}:${safeOutput(
            stderr
          )}`
        )
      );
    });
  });
}

function safePreAuthEnv(): NodeJS.ProcessEnv {
  return {
    PATH: process.env.PATH || '',
    HOME: process.env.HOME || os.tmpdir(),
    npm_config_loglevel: 'error',
  };
}

function safeOutput(value: string): string {
  return value
    .replace(/ghs_[A-Za-z0-9_]+/g, '[redacted-github-token]')
    .replace(/gh[pousr]_[A-Za-z0-9_]+/g, '[redacted-github-token]')
    .replace(/github_pat_[A-Za-z0-9_]+/g, '[redacted-github-token]')
    .slice(0, 200);
}
